# Test hypothesis: Each non-zero generates its own demo pattern, then union them
demo_out = np.array([list(map(int, line.split())) for line in demo_out_str.strip().split('\n')])

test_input = np.array([list(map(int, line.split())) for line in test_input_str.strip().split('\n')])
print("Test input non-zeros:")
positions = []
for r in range(11):
    for c in range(11):
        if test_input[r][c] != 0:
            positions.append((r,c))
            print(f"  ({r},{c}): value={test_input[r][c]}")

print(f"\nTotal {len(positions)} non-zero cells")

# Create prediction by overlaying demo pattern at each non-zero position
prediction = [[0]*11 for _ in range(11)]
for sr, sc in positions:
    # Place demo pattern centered at (sr, sc)
    for dr in range(11):
        for dc in range(11):
            nr, nc = sr + dr - 4, sc + dc - 5  # Center demo at (4,5) relative to (sr,sc)
            if 0 <= nr < 11 and 0 <= nc < 11:
                if demo_out[dr][dc] == 3:
                    prediction[nr][nc] = 3

print("\nPrediction (union of patterns from all non-zeros):")
for r, row in enumerate(prediction):
    print(f"Row {r}: {' '.join(map(str, row))}")
print(f"\nTotal threes: {(np.array(prediction)).sum()}")

